protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    List<E> edgeList = new ArrayList<>(tour);
    if(edgeList.isEmpty()){
        return new GraphPathImpl<>(graph, new ArrayList<>(), new ArrayList<>(), 0.0);
    }
    List<V> vertexList = new ArrayList<>();
    E first = edgeList.get(0);
    V start = graph.getEdgeSource(first);
    vertexList.add(start);
    double weight = 0.0;
    for(E e : edgeList){
        V target = graph.getEdgeTarget(e);
        vertexList.add(target);
        weight += graph.getEdgeWeight(e);
    }
    return new GraphPathImpl<>(graph, vertexList, edgeList, weight);
}

