public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    // Select the specified row
    table.setRowSelectionInterval(row, row);
    // Optionally select all columns in that row
    if (table.getColumnCount() > 0) {
        table.setColumnSelectionInterval(0, table.getColumnCount() - 1);
    }
    // Scroll the table to make the selected row visible
    Rectangle rect = table.getCellRect(row, 0, true);
    table.scrollRectToVisible(rect);
    // Delay repaint to allow the table to finish painting the new selection
    javax.swing.Timer repaintTimer = new javax.swing.Timer(200, e -> {
        table.repaint();
        ((javax.swing.Timer) e.getSource()).stop();
    });
    repaintTimer.setRepeats(false);
    repaintTimer.start();
}

