public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 3) return 3;
    int candidate = desiredCapacity;
    if ((candidate & 1) == 0) candidate++; // make odd
    while (true) {
        boolean isPrime = true;
        if (candidate <= 3) {
            isPrime = true;
        } else {
            if (candidate % 2 == 0 || candidate % 3 == 0) {
                isPrime = false;
            } else {
                for (int i = 5; i * i <= candidate; i += 6) {
                    if (candidate % i == 0 || candidate % (i + 2) == 0) {
                        isPrime = false;
                        break;
                    }
                }
            }
        }
        if (isPrime) return candidate;
        candidate += 2; // skip even numbers
    }
}

